"""Technician handoff report. Preview freely; export only with explicit consent (enforced in the route).
Nothing here contacts or books anyone."""
from __future__ import annotations

import html
from typing import Any

PATHWAYS = {"remote_expert": "Remote human expert", "local_technician": "Local technician"}
DISCLAIMERS = [
    "Generated by Sensora AI from the user's own session. No technician or expert has been contacted or booked by Sensora.",
    "Possible causes are unconfirmed AI suggestions, not diagnoses. Observations come from camera frames and may be wrong.",
    "Sensora cannot judge physical safety from images. The technician must assess the device on site.",
]


def build_handoff(*, session: dict[str, Any], summary: dict[str, Any], messages: list[dict[str, Any]], steps: list[dict[str, Any]],
                  evidence: list[dict[str, Any]], pathway: str, include_evidence: bool, evidence_consent: bool,
                  generated_at: str) -> dict[str, Any]:
    if pathway not in PATHWAYS:
        raise ValueError("unknown pathway")
    causes: dict[str, str] = {}
    concerns = [f"Safety flag raised during session: {c}" for c in summary["safety_events"]]
    for m in messages:
        st = (m.get("metadata") or {}).get("structured") or {}
        for c in st.get("likely_causes", []):
            causes[c["cause"]] = c.get("likelihood", "low")
        if st.get("safety_status") == "stop":
            concerns.append("Assistant issued a safety stop: " + m["content"][:200])
    unresolved = []
    if summary["device"] == "Not identified" or not session.get("device_model"):
        unresolved.append("Exact device model has not been confirmed.")
    unresolved += [f"Step not verified: {r['title']} ({r['outcome_label']})" for r in summary["steps"] if not r["visually_verified"] and r["outcome"] != "failed"]
    if not summary["observations"]:
        unresolved.append("No visual observations were recorded.")
    nxt = [summary["recommended_next"], "Do not open the device or touch internal wiring before a qualified technician has inspected it."]
    nxt.append("Be ready to show the device and any error codes on camera." if pathway == "remote_expert"
               else "Share this report with the technician before the visit so earlier steps are not repeated.")
    use_ev = bool(include_evidence and evidence_consent)
    return {
        "title": f"Technician handoff: {summary['device']}", "pathway": pathway, "pathway_label": PATHWAYS[pathway],
        "customer_issue": summary["issue"], "device": {"name": session.get("device_name"), "model": session.get("device_model")},
        "summary": summary, "status": summary["status"],
        "transcript": [{"role": m["role"], "text": m["content"][:400]} for m in messages if m.get("role") in ("user", "assistant")][-30:],
        "steps": summary["steps"],
        "possible_causes": [{"cause": c, "likelihood": l, "status": "Unconfirmed"} for c, l in causes.items()],
        "unresolved_questions": unresolved, "safety_concerns": concerns, "recommended_next_steps": nxt,
        "evidence_included": use_ev,
        "evidence_references": [{"id": e["id"], "captured_at": e["captured_at"], "note": e.get("note", ""), "expires_at": e.get("expires_at")} for e in evidence] if use_ev else [],
        "evidence_note": ("Evidence frame references are listed; image files are not embedded in this export." if use_ev else
                          "No visual evidence is included (no consent given, or not selected)."),
        "disclaimers": DISCLAIMERS + (["Contains simulated demo content."] if summary["simulated"] else []),
        "generated_at": generated_at,
    }


def handoff_markdown(h: dict[str, Any]) -> str:
    L = [f"# {h['title']}", f"*Pathway: {h['pathway_label']} | Generated {h['generated_at']}*", ""]
    L += [f"> {d}" for d in h["disclaimers"]] + ["", "## Customer-reported issue", h["customer_issue"], "",
          "## Device", f"- Name: {h['device']['name'] or 'unknown'}", f"- Model: {h['device']['model'] or 'unknown'}", f"- Status: {h['status']}", "",
          "## Steps attempted and outcomes"]
    L += [f"{i}. **{r['title']}**: {r['instruction']} | {r['outcome_label']} (reported by user: {'yes' if r['user_reported_complete'] else 'no'}; "
          f"visually verified: {'yes' if r['visually_verified'] else 'no'})" for i, r in enumerate(h["steps"], 1)] or ["- None"]
    L += ["", "## Possible causes (UNCONFIRMED)"] + [f"- {c['cause']} (likelihood {c['likelihood']}, unconfirmed)" for c in h["possible_causes"]] or ["- None suggested"]
    L += ["", "## Unresolved questions"] + [f"- {q}" for q in h["unresolved_questions"]] or ["- None"]
    L += ["", "## Safety concerns"] + [f"- {c}" for c in h["safety_concerns"]] or ["- None flagged"]
    L += ["", "## Recommended next steps"] + [f"- {n}" for n in h["recommended_next_steps"]]
    L += ["", "## Visual evidence", h["evidence_note"]] + [f"- {e['id']} ({e['captured_at']}) {e['note']}" for e in h["evidence_references"]]
    L += ["", "## Relevant transcript"] + [f"- **{t['role']}:** {t['text']}" for t in h["transcript"]]
    return "\n".join(L)


def handoff_html(h: dict[str, Any]) -> str:
    esc = html.escape
    def ul(items): return "<ul>" + "".join(f"<li>{esc(i)}</li>" for i in items) + "</ul>" if items else "<p>None</p>"
    steps = ul([f"{r['title']}: {r['outcome_label']} (user reported: {'yes' if r['user_reported_complete'] else 'no'}; visually verified: {'yes' if r['visually_verified'] else 'no'})" for r in h["steps"]])
    return (f"<!doctype html><html><head><meta charset='utf-8'><title>{esc(h['title'])}</title>"
            "<style>body{font-family:system-ui,sans-serif;max-width:760px;margin:2rem auto;line-height:1.5}blockquote{background:#fff4d6;padding:.5rem 1rem;margin:.4rem 0}</style></head><body>"
            f"<h1>{esc(h['title'])}</h1><p><em>{esc(h['pathway_label'])} | {esc(h['generated_at'])}</em></p>"
            + "".join(f"<blockquote>{esc(d)}</blockquote>" for d in h["disclaimers"])
            + f"<h2>Customer-reported issue</h2><p>{esc(h['customer_issue'])}</p>"
            f"<h2>Device</h2><p>{esc(h['device']['name'] or 'unknown')} / {esc(h['device']['model'] or 'unknown')}<br>Status: {esc(h['status'])}</p>"
            f"<h2>Steps attempted</h2>{steps}<h2>Possible causes (unconfirmed)</h2>"
            + ul([f"{c['cause']} ({c['likelihood']}, unconfirmed)" for c in h["possible_causes"]])
            + f"<h2>Unresolved questions</h2>{ul(h['unresolved_questions'])}<h2>Safety concerns</h2>{ul(h['safety_concerns'])}"
            f"<h2>Recommended next steps</h2>{ul(h['recommended_next_steps'])}<h2>Visual evidence</h2><p>{esc(h['evidence_note'])}</p>"
            + ul([f"{e['id']} ({e['captured_at']}) {e['note']}" for e in h["evidence_references"]])
            + "<h2>Relevant transcript</h2>" + ul([f"{t['role']}: {t['text']}" for t in h["transcript"]]) + "</body></html>")
